from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def get_allowed_cells(self, grid, prev_move):
        if prev_move is None:
            allowed = []
            n = len(grid)
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 0:
                        allowed.append((r, c))
            return allowed
        else:
            last_r, last_c = prev_move[0]
            allowed = []
            n = len(grid)
            for c in range(n):
                if grid[last_r][c] == 0:
                    allowed.append((last_r, c))
            for r in range(n):
                if grid[r][last_c] == 0 and (r, last_c) not in allowed:
                    allowed.append((r, last_c))
            if not allowed:
                for r in range(n):
                    for c in range(n):
                        if grid[r][c] == 0:
                            allowed.append((r, c))
            return allowed

    def is_valid(self, grid, r, c, num):
        if num in grid[r]:
            return False
        for row in grid:
            if row[c] == num:
                return False
        n = len(grid)
        sqrt_n = int(n ** 0.5)
        start_r = (r // sqrt_n) * sqrt_n
        start_c = (c // sqrt_n) * sqrt_n
        for i in range(start_r, start_r + sqrt_n):
            for j in range(start_c, start_c + sqrt_n):
                if grid[i][j] == num:
                    return False
        return True

    def possible_numbers(self, grid, r, c):
        if grid[r][c] != 0:
            return []
        return [num for num in range(1, len(grid) + 1) if self.is_valid(grid, r, c, num)]

    def is_winning_move(self, grid, move):
        new_grid = [row.copy() for row in grid]
        (r, c), num = move
        new_grid[r][c] = num
        opponent_prev = ( (r, c), num )
        opp_allowed = self.get_allowed_cells(new_grid, opponent_prev)
        for (opp_r, opp_c) in opp_allowed:
            if len(self.possible_numbers(new_grid, opp_r, opp_c)) > 0:
                return False
        return True

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]

        allowed_cells = self.get_allowed_cells(grid, prev_move)
        possible_moves = []
        for (r, c) in allowed_cells:
            for num in self.possible_numbers(grid, r, c):
                possible_moves.append(((r, c), num))

        winning_moves = []
        for move in possible_moves:
            if self.is_winning_move(grid, move):
                winning_moves.append(move)

        if winning_moves:
            move = winning_moves[0]
        else:
            min_opp = float('inf')
            best_move = None
            for candidate in possible_moves:
                new_grid = [row.copy() for row in grid]
                (r, c), num = candidate
                new_grid[r][c] = num
                opp_prev = ( (r, c), num )
                opp_allowed = self.get_allowed_cells(new_grid, opp_prev)
                total = 0
                for (opp_r, opp_c) in opp_allowed:
                    total += len(self.possible_numbers(new_grid, opp_r, opp_c))
                if total < min_opp or (total == min_opp and not best_move):
                    min_opp = total
                    best_move = candidate
            move = best_move if best_move else possible_moves[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )

