    # Check subgrid
    n = len(grid)
    sqrt_n = int(n ** 0.5)
    sub_r = (r // sqrt_n) * sqrt_n
    sub_c = (c // sqrt_n) * sqrt_n
    for i in range(sub_r, sub_r + sqrt_n):
        for j in range(sub_c, sub_c + sqrt_n):
            if grid[i][j] == val:
                return False
    return True


def get_current_candidates(grid, prev_move):
    n = len(grid)
    empty_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 0]
    if not prev_move:
        return empty_cells
    else:
        prev_r, prev_c = prev_move[0]
        same_row_or_col = []
        for (r, c) in empty_cells:
            if r == prev_r or c == prev_c:
                same_row_or_col.append((r, c))
        return same_row_or_col if same_row_or_col else empty_cells


