        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]
        n = len(grid)

        # Get current candidate cells
        candidate_cells = get_current_candidates(grid, prev_move)

        # Generate all valid moves
        valid_moves = []
        for (r, c) in candidate_cells:
            for val in range(1, n + 1):
                if is_valid_move(grid, r, c, val):
                    valid_moves.append((r, c, val))

        # Check for winning move
        winning_move = None
        for move in valid_moves:
            r, c, val = move
            new_grid = [row.copy() for row in grid]
            new_grid[r][c] = val
            opponent_candidates = get_current_candidates(new_grid, [(r, c), val])

            opponent_has_valid = False
            for (or_, oc) in opponent_candidates:
                for v in range(1, n + 1):
                    if is_valid_move(new_grid, or_, oc, v):
                        opponent_has_valid = True
                        break
                if opponent_has_valid:
                    break
            if not opponent_has_valid:
                winning_move = [(r, c), val]
                break

        if winning_move:
