            first_move = valid_moves[0]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=[(first_move[0], first_move[1]), first_move[2], type='custom')]
            )
        else:
            # Fallback, though this case should not occur in a valid game
