            allowed_cells = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]
        else:
            prev_row, prev_col = prev_move[0][0], prev_move[0][1]
            same_row = [(prev_row, c) for c in range(N) if grid[prev_row][c] == 0]
            same_col = [(r, prev_col) for r in range(N) if grid[r][prev_col] == 0]
            allowed_cells = list({(r, c) for r, c in same_row + same_col})
            if not allowed_cells:
                allowed_cells = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]

