            existing_col = {grid[i][c] for i in range(N) if grid[i][c] != 0}
            subgrid_row = (r // sub_size) * sub_size
            subgrid_col = (c // sub_size) * sub_size
            existing_subgrid = set()
            for i in range(subgrid_row, subgrid_row + sub_size):
